// smoke.spec.js — Extract Audio from Video: the acceptance checks from SPEC.md, run on bundled fictional fixtures.
// sample-video.mp4 (12 s, colour bar + three tone melody) and silent-video.mp4 (no audio track) are generated by
// tests/tools/make-video-fixtures.js.
const { test, expect } = require('@playwright/test');
const fs = require('fs');
const path = require('path');

const fixture = (name) => path.join(__dirname, 'fixtures', name);

// Simulates dragging files from the desktop onto the drop zone.
async function dropFiles(page, files) {
  const payload = files.map(({ file, name, type }) => ({ name, type, b64: fs.readFileSync(fixture(file)).toString('base64') }));
  await page.evaluate((list) => {
    const dt = new DataTransfer();
    for (const f of list) dt.items.add(new File([Uint8Array.from(atob(f.b64), (c) => c.charCodeAt(0))], f.name, { type: f.type }));
    document.getElementById('dropzone').dispatchEvent(new DragEvent('drop', { dataTransfer: dt, bubbles: true, cancelable: true }));
  }, payload);
}

async function loadSample(page, name = 'sample-video.mp4') {
  await dropFiles(page, [{ file: 'sample-video.mp4', name, type: 'video/mp4' }]);
  await expect(page.locator('#duration')).toBeVisible();
}

async function extractAndDownload(page) {
  await page.click('#extract');
  await expect(page.locator('.eav-result')).toBeVisible({ timeout: 30_000 });
  const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
  const bytes = fs.readFileSync(await download.path());
  return { download, bytes };
}

function parseWav(bytes) {
  return {
    riff: bytes.toString('ascii', 0, 4),
    wave: bytes.toString('ascii', 8, 12),
    channels: bytes.readUInt16LE(22),
    sampleRate: bytes.readUInt32LE(24),
    bits: bytes.readUInt16LE(34),
    dataBytes: bytes.readUInt32LE(40),
  };
}

test.describe('Extract Audio from Video', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('./');
  });

  test('dropping sample-video.mp4 shows its name, duration and an audio waveform', async ({ page }) => {
    await expect(page.locator('#options')).toBeHidden();
    await loadSample(page);
    await expect(page.locator('#file-name')).toHaveText('sample-video.mp4');
    await expect(page.locator('#duration')).toContainText(/Duration 0:1[12]\.\d/);
    const secs = Number(await page.locator('#duration').getAttribute('data-seconds'));
    expect(secs).toBeGreaterThan(11);
    expect(secs).toBeLessThan(13);
    await expect(page.locator('#end')).toHaveValue(/^0:1[12]\.\d$/);
    // The waveform canvas is visible and actually painted.
    await expect(page.locator('#waveform')).toBeVisible();
    const painted = await page.evaluate(() => {
      const c = document.getElementById('waveform');
      const d = c.getContext('2d').getImageData(0, 0, c.width, c.height).data;
      let n = 0;
      for (let i = 3; i < d.length; i += 4) if (d[i] > 0) n++;
      return n / (c.width * c.height);
    });
    expect(painted).toBeGreaterThan(0.05);
    await expect(page.locator('#format')).toHaveValue('mp3');
    await expect(page.locator('#bitrate')).toHaveValue('192');
  });

  test('MP3 at 128 kbps downloads a real MP3 named after the video', async ({ page }) => {
    await loadSample(page);
    await page.selectOption('#format', 'mp3');
    await page.selectOption('#bitrate', '128');
    const { download, bytes } = await extractAndDownload(page);
    expect(download.suggestedFilename()).toBe('sample-video.mp3');
    expect(bytes.length).toBeGreaterThan(1024);
    // MPEG audio frame sync (lamejs writes no ID3 tag): 11 set bits.
    expect(bytes[0]).toBe(0xff);
    expect(bytes[1] & 0xe0).toBe(0xe0);
    // ~12 s at 128 kbps is ~190 KB; allow encoder padding.
    expect(bytes.length).toBeGreaterThan(150_000);
    expect(bytes.length).toBeLessThan(230_000);
    await expect(page.locator('.eav-result .result__info')).toContainText('MP3 · 128 kbps');
    await expect(page.locator('#progress-label')).toHaveText('Done: 100%');
    // The preview player can load the result.
    const dur = await page.locator('.eav-player').evaluate((a) => new Promise((r) => {
      if (a.readyState >= 1) r(a.duration); else a.addEventListener('loadedmetadata', () => r(a.duration), { once: true });
    }));
    expect(dur).toBeGreaterThan(11);
  });

  test('WAV downloads a file starting with the RIFF header', async ({ page }) => {
    await loadSample(page);
    await page.selectOption('#format', 'wav');
    await expect(page.locator('#bitrate-field')).toBeHidden();
    const { download, bytes } = await extractAndDownload(page);
    expect(download.suggestedFilename()).toBe('sample-video.wav');
    expect(bytes.toString('ascii', 0, 4)).toBe('RIFF');
    const wav = parseWav(bytes);
    expect(wav.wave).toBe('WAVE');
    expect(wav.channels).toBe(2);
    expect(wav.bits).toBe(16);
    expect(wav.dataBytes + 44).toBe(bytes.length);
    // The sound is really there: the melody peaks at about 0.3 of full scale.
    let peak = 0;
    for (let i = 44; i < bytes.length; i += 2) peak = Math.max(peak, Math.abs(bytes.readInt16LE(i)));
    expect(peak).toBeGreaterThan(5000);
  });

  test('a video without an audio track says there is no sound', async ({ page }) => {
    await page.setInputFiles('#file-input', fixture('silent-video.mp4'));
    const err = page.locator('#results .alert--error');
    await expect(err).toBeVisible();
    await expect(err).toContainText(/no sound/i);
    await expect(err).toContainText('no audio track');
    await expect(page.locator('#options')).toBeHidden();
  });

  test('start and end times limit the extracted length', async ({ page }) => {
    await loadSample(page);
    await page.selectOption('#format', 'wav');
    await page.fill('#start', '2');
    await page.fill('#end', '0:05.5');
    await page.check('#mono');
    const { bytes } = await extractAndDownload(page);
    const wav = parseWav(bytes);
    expect(wav.channels).toBe(1);
    const seconds = wav.dataBytes / (wav.sampleRate * wav.channels * 2);
    expect(seconds).toBeCloseTo(3.5, 2);
    await expect(page.locator('.eav-result .result__info')).toContainText('mono · 0:03.5');

    // Same range as MP3 is much smaller than the full-length MP3 would be.
    await page.selectOption('#format', 'mp3');
    await page.selectOption('#bitrate', '128');
    const mp3 = await extractAndDownload(page);
    expect(mp3.bytes.length).toBeGreaterThan(40_000);
    expect(mp3.bytes.length).toBeLessThan(80_000);
  });

  test('an invalid range shows an inline error instead of extracting', async ({ page }) => {
    await loadSample(page);
    await page.fill('#start', '8');
    await page.fill('#end', '4');
    await page.click('#extract');
    await expect(page.locator('#results .alert--error')).toContainText('Start must be before end');
    await page.fill('#end', 'abc');
    await page.click('#extract');
    await expect(page.locator('#results .alert--error')).toContainText('times like');
    await expect(page.locator('.eav-result')).toHaveCount(0);
  });

  test('wrong file types are rejected, also when mixed with a video', async ({ page }) => {
    await page.setInputFiles('#file-input', fixture('sample.png'));
    await expect(page.locator('#results .alert--error')).toContainText('not a video or audio file');
    await expect(page.locator('#options')).toBeHidden();

    await dropFiles(page, [
      { file: 'sample.png', name: 'sample.png', type: 'image/png' },
      { file: 'sample-video.mp4', name: 'sample-video.mp4', type: 'video/mp4' },
    ]);
    await expect(page.locator('#duration')).toBeVisible();
    await expect(page.locator('#results .alert--error')).toContainText('Skipped sample.png');
  });

  test('keyboard: Enter starts extraction and space toggles the player; Unicode names are kept', async ({ page }) => {
    await loadSample(page, 'Café concert ♪ 2026.mp4');
    await page.selectOption('#format', 'wav');
    await page.focus('#end');
    await page.keyboard.press('Enter');
    await expect(page.locator('.eav-result')).toBeVisible({ timeout: 30_000 });
    await expect(page.locator('#download')).toHaveText('Download Café concert ♪ 2026.wav');
    const [download] = await Promise.all([page.waitForEvent('download'), page.click('#download')]);
    expect(download.suggestedFilename()).toBe('Café concert ♪ 2026.wav');

    await page.locator('.eav-player').evaluate((a) => { a.muted = true; });
    await page.locator('h1').click();
    await page.keyboard.press(' ');
    await expect.poll(() => page.locator('.eav-player').evaluate((a) => a.paused)).toBe(false);
    await page.keyboard.press(' ');
    await expect.poll(() => page.locator('.eav-player').evaluate((a) => a.paused)).toBe(true);
  });

  test('works at 390px wide: loads, extracts and downloads without horizontal scroll', async ({ page }) => {
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    const dz = await page.locator('#dropzone').boundingBox();
    expect(dz.y + dz.height).toBeLessThan(844 * 1.2);
    await loadSample(page, 'a-rather-long-video-file-name-from-a-phone-camera-0001.mp4');
    const { bytes } = await extractAndDownload(page);
    expect(bytes.length).toBeGreaterThan(1024);
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc).toBeLessThanOrEqual(widths.win + 1);
    for (const sel of ['#extract', '#download', '.eav-player', '#waveform']) {
      const box = await page.locator(sel).boundingBox();
      expect(box.x).toBeGreaterThanOrEqual(0);
      expect(box.x + box.width).toBeLessThanOrEqual(391);
    }
  });

  test('__demo shows a finished result from the bundled clip', async ({ page }) => {
    await page.evaluate(() => window.__demo());
    await expect(page.locator('#file-name')).toHaveText('Sample Video.mp4');
    await expect(page.locator('.eav-result .result__info')).toContainText('0:08.0');
    await expect(page.locator('#download')).toHaveText('Download Sample Video.mp3');
  });
});
